const vehicleCanonicalModelIDs = `-- name: VehicleCanonicalModelIDs :many
SELECT m.id, (
    SELECT g.id FROM catalog_models g
    JOIN catalog_brands gb ON gb.id = g.brand_id
    WHERE g.group_key = m.group_key AND gb.display_brand_id = b.display_brand_id
    ORDER BY g.id
    LIMIT 1
)::bigint AS canonical_id
FROM catalog_models m
JOIN catalog_brands b ON b.id = m.brand_id
WHERE m.id = ANY($1::bigint[])
`

type VehicleCanonicalModelIDsRow struct {
	ID          int64 `json:"id"`
	CanonicalID int64 `json:"canonical_id"`
}

// Platform catalog (not organization scoped): the grouped model of each
// catalog model, the lowest id among the models with the same group key
// under the TSB brands of one display brand (the id tenant pickers use).
func (q *Queries) VehicleCanonicalModelIDs(ctx context.Context, ids []int64) ([]VehicleCanonicalModelIDsRow, error) {
	rows, err := q.db.Query(ctx, vehicleCanonicalModelIDs, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []VehicleCanonicalModelIDsRow{}
	for rows.Next() {
		var i VehicleCanonicalModelIDsRow
		if err := rows.Scan(&i.ID, &i.CanonicalID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const vehiclePlateTaken = `-- name: VehiclePlateTaken :one
SELECT EXISTS (
    SELECT 1 FROM vehicles
    WHERE organization_id = $1
      AND plate_key = upper(regexp_replace($2::text, '[^A-Za-z0-9]', '', 'g'))
      AND deleted_at IS NULL
      AND is_active
      AND ($3::uuid IS NULL OR uuid <> $3)
)::boolean
`

type VehiclePlateTakenParams struct {
	OrganizationID int64       `json:"organization_id"`
	Plate          string      `json:"plate"`
	ExcludeUuid    pgtype.UUID `json:"exclude_uuid"`
}

// Plates are compared by their key (letters and digits, upper-case) among
// live, active vehicles.
func (q *Queries) VehiclePlateTaken(ctx context.Context, arg VehiclePlateTakenParams) (bool, error) {
	row := q.db.QueryRow(ctx, vehiclePlateTaken, arg.OrganizationID, arg.Plate, arg.ExcludeUuid)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}
